-- Schema-only production contract, September 8, 2026. No production rows.
-- Foreign keys are omitted so regressions use isolated synthetic identities.
CREATE TYPE "program_category" AS ENUM ('EARLY_DEVELOPMENT','GYMNASTICS','VORTEX_NINJA','ATHLETICISM_ACCELERATOR','ADULT_FITNESS','HOMESCHOOL');
CREATE TYPE "skill_level" AS ENUM ('EARLY_STAGE','BEGINNER','INTERMEDIATE','ADVANCED','ELITE');
CREATE TYPE "user_role" AS ENUM ('MASTER_ADMIN','ADMIN','COACH','MEMBER_ATHLETE','MEMBER');
