CREATE INDEX IF NOT EXISTS idx_drop_in_slot_date ON public.drop_in_registration USING btree (slot_group_id, class_date, status);
CREATE UNIQUE INDEX IF NOT EXISTS uq_drop_in_lifetime_trial_member ON public.drop_in_registration USING btree (member_id) WHERE ((benefit_type = 'free_trial'::text) AND (member_id IS NOT NULL) AND (status <> 'cancelled'::text));
CREATE INDEX IF NOT EXISTS idx_drop_in_member_benefit_created ON public.drop_in_registration USING btree (member_id, benefit_type, created_at) WHERE (status = ANY (ARRAY['account_required'::text, 'payment_pending'::text, 'confirmed'::text, 'attended'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS uq_drop_in_lifetime_trial_contact_athlete ON public.drop_in_registration USING btree (lower(email), lower(first_name), lower(last_name)) WHERE ((benefit_type = 'free_trial'::text) AND (member_id IS NULL) AND (status <> 'cancelled'::text));
CREATE UNIQUE INDEX IF NOT EXISTS uq_drop_in_pending_contact_occurrence ON public.drop_in_registration USING btree (lower(email), lower(first_name), lower(last_name), slot_group_id, class_date) WHERE ((member_id IS NULL) AND (status = 'account_required'::text));
CREATE INDEX IF NOT EXISTS idx_drop_in_registration_member_class_date ON public.drop_in_registration USING btree (member_id, class_date DESC, id DESC) WHERE ((member_id IS NOT NULL) AND (status = ANY (ARRAY['confirmed'::text, 'attended'::text])));
CREATE UNIQUE INDEX IF NOT EXISTS billing_payment_fact_audit_job_pkey ON public.billing_payment_fact_audit_job USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS billing_payment_fact_audit_jo_billing_payment_id_payment_ex_key ON public.billing_payment_fact_audit_job USING btree (billing_payment_id, payment_external_status);
CREATE INDEX IF NOT EXISTS idx_billing_payment_fact_audit_job_due ON public.billing_payment_fact_audit_job USING btree (run_status, next_attempt_at, id);
CREATE UNIQUE INDEX IF NOT EXISTS billing_monthly_invoice_pkey ON public.billing_monthly_invoice USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS billing_monthly_invoice_family_billing_account_id_billing_m_key ON public.billing_monthly_invoice USING btree (family_billing_account_id, billing_month);
CREATE UNIQUE INDEX IF NOT EXISTS uq_billing_monthly_invoice_stripe_invoice ON public.billing_monthly_invoice USING btree (stripe_invoice_id) WHERE (stripe_invoice_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_billing_monthly_invoice_account_status ON public.billing_monthly_invoice USING btree (family_billing_account_id, status, billing_month DESC);
CREATE INDEX IF NOT EXISTS idx_billing_monthly_invoice_automatic_attempt ON public.billing_monthly_invoice USING btree (family_billing_account_id, billing_month, automatic_attempt_count);
